   private static final Pattern SHINE_LOOSE_UNIFORM = Pattern.compile("(?m)^[\\t ]*uniform\\s+(?:int|float|vec2|vec3|vec4|ivec3|mat4)\\s+u_Shine[A-Za-z0-9_]+(?:\\[[^;\\r\\n]+])?;[\\t ]*(?://[^\\r\\n]*)?\\r?\\n?");
